import { useEffect, useCallback } from 'react';
import { ExtensionToWebviewMessage, WebviewToExtensionMessage } from '../types/messages';

// Get the VS Code API injected by the webview HTML
// @ts-ignore
const vscode = window.vscode || {
  postMessage: () => {
    console.warn('vscode API not found - running outside of extension?');
  }
};

type MessageHandler = (message: ExtensionToWebviewMessage) => void;

/**
 * Hook for typed messaging between React and the VS Code Extension Host.
 */
export function useMessaging(handler?: MessageHandler) {
  useEffect(() => {
    const listener = (event: MessageEvent) => {
      const message = event.data as ExtensionToWebviewMessage;
      if (handler) {
        handler(message);
      }
    };

    window.addEventListener('message', listener);
    return () => window.removeEventListener('message', listener);
  }, [handler]);

  const postMessage = useCallback((message: WebviewToExtensionMessage) => {
    vscode.postMessage(message);
  }, []);

  return { postMessage };
}

import * as vscode from 'vscode';
import { CodebaseIndexer } from './indexing/indexer';
import { ProviderRegistry } from './providers/registry';
import { Logger } from './utils/logger';
import { Arc1610ViewProvider } from './webview/viewProvider';

let indexer: CodebaseIndexer;
let providerRegistry: ProviderRegistry;
let logger: Logger;

export async function activate(context: vscode.ExtensionContext) {
  // Initialize logger
  logger = Logger.getInstance();
  logger.info('Arc1610 activating...');

  try {
    // Initialize core services
    providerRegistry = new ProviderRegistry(context.secrets);

    const indexerConfig = CodebaseIndexer.readConfig();
    indexer = new CodebaseIndexer(indexerConfig);

    // Register webview provider
    const viewProvider = new Arc1610ViewProvider(context.extensionUri, providerRegistry, indexer);

    context.subscriptions.push(
      vscode.window.registerWebviewViewProvider(
        Arc1610ViewProvider.viewType,
        viewProvider,
        {
          webviewOptions: { retainContextWhenHidden: true },
        }
      )
    );

    // Register commands
    context.subscriptions.push(
      vscode.commands.registerCommand('arc1610.openChat', () => {
        vscode.commands.executeCommand('arc1610.chatView.focus');
      }),

      vscode.commands.registerCommand('arc1610.newChat', () => {
        viewProvider.newChat();
      }),

      vscode.commands.registerCommand('arc1610.indexWorkspace', () => {
        indexer.indexWorkspace(false); // incremental
      }),

      vscode.commands.registerCommand('arc1610.reindexWorkspace', () => {
        indexer.indexWorkspace(true); // full
      }),

      vscode.commands.registerCommand('arc1610.cancelIndexing', () => {

}),

vscode.commands.registerCommand('arc1610.cancelIndexing', () => {
  indexer.cancelIndexing();
}),

vscode.commands.registerCommand('arc1610.addFileContext', async () => {
  const editor = vscode.window.activeTextEditor;
  if (editor) {
    const filepath = editor.document.uri.fsPath;
    viewProvider.addContext(filepath);
  } else {
    vscode.window.showInformationMessage('No active editor to add file from.');
  }
}),

vscode.commands.registerCommand('arc1610.addSelectionContext', async () => {
  const editor = vscode.window.activeTextEditor;
  if (editor) {
    const filepath = editor.document.uri.fsPath;
    const selection = editor.document.getText(editor.selection);
    if (selection) {
      viewProvider.addContext(filepath, undefined, selection);
    } else {
      vscode.window.showInformationMessage('No text selected.');
    }
  }
}),

vscode.commands.registerCommand('arc1610.configureProvider', async () => {
  const providers = providerRegistry.getSupportedProviders();

  // Show QuickPick to select provider
  const selected = await vscode.window.showQuickPick(providers, {
    title: 'Select AI Provider to Configure',
  });

  if (selected) {
    // If it needs an API key (not Ollama), prompt for it
    if (selected !== 'ollama') {
      await providerRegistry.promptForApiKey(selected);
    }

    // Update setting
    await vscode.workspace.getConfiguration('arc1610').update('provider', selected, true);
    viewProvider.sendConfig();
    vscode.window.showInformationMessage(`Provider set to ${selected}`);

          await vscode.workspace.getConfiguration('arc1610').update('provider', selected, true);
          viewProvider.sendConfig();
          vscode.window.showInformationMessage(`Provider set to ${selected}`);
        }
      })
    );

    // Listen for configuration changes
    context.subscriptions.push(
      vscode.workspace.onDidChangeConfiguration(e => {
        if (e.affectsConfiguration('arc1610.indexing') || e.affectsConfiguration('arc1610.ollama')) {
          indexer.updateConfig(CodebaseIndexer.readConfig());
        }
        if (e.affectsConfiguration('arc1610.provider') || e.affectsConfiguration('arc1610.modelName')) {
          viewProvider.sendConfig();
        }
      })
    );

    // Auto-start incremental indexing if enabled
    const autoIndex = vscode.workspace.getConfiguration('arc1610').get<boolean>('indexing.enabled', true);
    if (autoIndex && vscode.workspace.workspaceFolders) {
      // Small delay to not block startup
      setTimeout(() => {
        indexer.indexWorkspace(false).catch(err => {
          logger.error('Auto-indexing failed', err);
        });
      }, 5000);
    }

    logger.info('Arc1610 activation complete');

  } catch (error) {
    logger.error('Failed to activate Arc1610', error);
    vscode.window.showErrorMessage(`Arc1610 failed to activate: ${error instanceof Error ? error.message : String(error)}`);
  }
}

export function deactivate() {
  indexer?.dispose();
  providerRegistry?.dispose();
  logger?.dispose();
}

/**
 * Typed message protocol between webview and extension host.
 * 
 * All communication goes through VS Code's postMessage mechanism.
 * Messages are validated on receipt — the webview never has direct filesystem
 * or network access.
 */

import { IndexingProgress } from '../indexing/types';

// ─── Messages from Webview to Extension ────────────────────────────────────

export type WebviewToExtensionMessage =
  | { type: 'sendMessage'; text: string; contextFiles?: string[] }
  | { type: 'cancelGeneration' }
  | { type: 'newChat' }
  | { type: 'approveAction'; approved: boolean }
  | { type: 'getConfig' }
  | { type: 'setProvider'; provider: string }
  | { type: 'setModel'; model: string }
  | { type: 'setApiKey'; provider: string; key: string }
  | { type: 'testConnection' }
  | { type: 'startIndexing'; fullReindex?: boolean }
  | { type: 'cancelIndexing' }
  | { type: 'getIndexStatus' }
  | { type: 'webviewReady' };

// ─── Messages from Extension to Webview ────────────────────────────────────

export type ExtensionToWebviewMessage =
  | { type: 'streamContent'; content: string }
  | { type: 'streamDone' }
  | { type: 'streamError'; error: string }
  | { type: 'streamCancelled' }
  | { type: 'toolCall'; toolName: string; args: Record<string, unknown> }
  | { type: 'toolResult'; toolName: string; content: string; success: boolean }
  | { type: 'approvalRequest'; toolName: string; description: string; diff?: string; filepath?: string }
  | { type: 'config'; provider: string; model: string; hasApiKey: boolean; availableProviders: string[] }
  | { type: 'connectionResult'; success: boolean; models?: string[]; error?: string }
  | { type: 'indexingProgress'; progress: IndexingProgress }
  | { type: 'indexStatus'; indexed: boolean; entryCount: number; fileCount: number; inProgress: boolean }

  | { type: 'connectionResult'; success: boolean; models?: string[]; error?: string }
  | { type: 'indexingProgress'; progress: IndexingProgress }
  | { type: 'indexStatus'; indexed: boolean; entryCount: number; fileCount: number; inProgress: boolean }
  | { type: 'addContext'; filepath: string; content?: string; selection?: string };

/**
 * Validate that a message from the webview is well-formed.
 * Returns the validated message or null if invalid.
 */
export function validateWebviewMessage(data: unknown): WebviewToExtensionMessage | null {
  if (typeof data !== 'object' || data === null) {
    return null;
  }

  const msg = data as Record<string, unknown>;
  if (typeof msg.type !== 'string') {
    return null;
  }

  const validTypes: Set<string> = new Set([
    'sendMessage', 'cancelGeneration', 'newChat', 'approveAction',
    'getConfig', 'setProvider', 'setModel', 'setApiKey',
    'testConnection', 'startIndexing', 'cancelIndexing',
    'getIndexStatus', 'webviewReady',
  ]);

  if (!validTypes.has(msg.type)) {
    return null;
  }

  // Type-specific validation
  switch (msg.type) {
    case 'sendMessage':
      if (typeof msg.text !== 'string' || msg.text.trim().length === 0) {
        return null;
      }
      break;
    case 'approveAction':
      if (typeof msg.approved !== 'boolean') {
        return null;
      }
      break;
    case 'setProvider':
      if (typeof msg.provider !== 'string') {
        return null;
      }
      break;
    case 'setModel':
      if (typeof msg.model !== 'string') {
        return null;
      }
      break;
    case 'setApiKey':
      if (typeof msg.provider !== 'string' || typeof msg.key !== 'string') {
        return null;
      }
      break;
  }

  return msg as WebviewToExtensionMessage;
}

import * as vscode from 'vscode';

/**
 * Generate a strict Content Security Policy for the webview.
 * 
 * Prevents execution of inline scripts (except our specific nonce),
 * restricts connect-src (since API calls happen in the extension host, not webview),
 * and prevents framing.
 */
export function getCsp(webview: vscode.Webview, nonce: string): string {
  return [
    `default-src 'none'`,
    // Allow styles from the extension uri and inline styles (needed by React sometimes)
    `style-src ${webview.cspSource} 'unsafe-inline'`,
    // Allow scripts with the generated nonce, plus standard webview sources
    `script-src ${webview.cspSource} 'unsafe-inline' 'unsafe-eval' 'nonce-${nonce}'`,
    // Allow fonts if needed
    `font-src ${webview.cspSource}`,
    // The webview doesn't make direct API calls — all network happens in the extension host
    `connect-src 'none'`,
    // Images allowed from extension and data URIs
    `img-src ${webview.cspSource} data:`,
    // Frame control
    `frame-src 'none'`,
  ].join('; ');
}

/**
 * Webview Provider for the ARC1610 sidebar chat interface.
 * 
 * Handles the lifecycle of the webview, message routing to the agent loop,
 * configuration updates, and indexing status reporting.
 */

import * as vscode from 'vscode';
import { AgentLoop } from '../agent/agentLoop';
import { CodebaseIndexer } from '../indexing/indexer';
import { ProviderRegistry } from '../providers/registry';
import { ChatMessage } from '../providers/types';
import { Logger } from '../utils/logger';
import { ExtensionToWebviewMessage, validateWebviewMessage, WebviewToExtensionMessage } from './messageTypes';
import { getCsp } from './securityPolicy';
import { OllamaManager } from '../utils/ollamaManager';

export class Arc1610ViewProvider implements vscode.WebviewViewProvider {
  public static readonly viewType = 'arc1610.chatView';

  private view?: vscode.WebviewView;
  private chatHistory: ChatMessage[] = [];
  private agent: AgentLoop | null = null;
  private readonly logger = Logger.getInstance();

  constructor(
    private readonly extensionUri: vscode.Uri,
    private readonly providerRegistry: ProviderRegistry,
    private readonly indexer: CodebaseIndexer,
  ) {}

  public resolveWebviewView(
    webviewView: vscode.WebviewView,
    context: vscode.WebviewViewResolveContext,
    _token: vscode.CancellationToken,
  ) {
    this.view = webviewView;

    // Set webview options
    webviewView.webview.options = {
      enableScripts: true,
      localResourceRoots: [this.extensionUri],
    };

    // Set HTML content
    webviewView.webview.html = this.getHtmlForWebview(webviewView.webview);

    // Handle messages from the webview
    webviewView.webview.onDidReceiveMessage(
      (data) => this.handleMessage(data),
      undefined,
      [], // disposables
    );

    [], // disposables
  );

  // Send initial configuration and index status
  this.sendConfig();
  this.sendIndexStatus();

  // Subscribe to indexer progress events
  this.indexer.onProgress((progress) => {
    this.postMessage({ type: 'indexingProgress', progress });
    if (progress.status === 'complete' || progress.status === 'error' || progress.status === 'cancelled') {
      this.sendIndexStatus();
    }
  });
}

/**
 * Start a new chat session.
 */
public newChat() {
  this.chatHistory = [];
  this.agent?.cancel();
  this.agent = null;

  if (this.view) {
    // In a real implementation, we'd tell the UI to clear its state
    // For now, we'll let the user message trigger a fresh start on the backend
    this.postMessage({ type: 'streamCancelled' }); 
  }
}

/**
 * Add context to the current chat (from editor commands).
 */
public addContext(filepath: string, content?: string, selection?: string) {
  if (this.view) {
    this.view.show?.(true);
    this.postMessage({
      type: 'addContext',
      filepath,
      content,
      selection,
    });
  }
}

/**
 * Send configuration to the webview.
 */
public async sendConfig() {
  try {
    const config = await this.providerRegistry.readConfig();
