/**
 * Typed error classes for ARC1610.
 * Each error type carries a reason code for structured error handling.
 */

export enum ErrorReason {
  // Provider errors
  ProviderNotConfigured = 'PROVIDER_NOT_CONFIGURED',
  ProviderConnectionFailed = 'PROVIDER_CONNECTION_FAILED',
  ProviderAuthFailed = 'PROVIDER_AUTH_FAILED',
  ProviderRateLimit = 'PROVIDER_RATE_LIMIT',
  ProviderModelNotFound = 'PROVIDER_MODEL_NOT_FOUND',
  ProviderContextLength = 'PROVIDER_CONTEXT_LENGTH',
  ProviderTimeout = 'PROVIDER_TIMEOUT',

  // Indexing errors
  IndexingFailed = 'INDEXING_FAILED',
  IndexCorrupted = 'INDEX_CORRUPTED',
  EmbeddingFailed = 'EMBEDDING_FAILED',
  FileReadFailed = 'FILE_READ_FAILED',
  FileTooLarge = 'FILE_TOO_LARGE',

  // Agent errors
  AgentIterationLimit = 'AGENT_ITERATION_LIMIT',
  ToolExecutionFailed = 'TOOL_EXECUTION_FAILED',
  ToolNotFound = 'TOOL_NOT_FOUND',
  ToolValidationFailed = 'TOOL_VALIDATION_FAILED',

  // Security errors
  PathTraversal = 'PATH_TRAVERSAL',
  FileSecurityConcern = 'FILE_SECURITY_CONCERN',
  OutsideWorkspace = 'OUTSIDE_WORKSPACE',

  // General
  Cancelled = 'CANCELLED',
  ConfigInvalid = 'CONFIG_INVALID',
  Unknown = 'UNKNOWN',
}

export class Arc1610Error extends Error {
  constructor(
    public readonly reason: ErrorReason,
    message: string,
    public readonly cause?: Error,
  ) {
    super(message);
    this.name = 'Arc1610Error';
  }

  /**
   * Returns a user-friendly message that doesn't expose internal details.
   */
  get userMessage(): string {
    switch (this.reason) {
      case ErrorReason.ProviderNotConfigured:
        return 'No AI provider configured. Open Arc1610 settings to set up a provider.';
      case ErrorReason.ProviderConnectionFailed:

      case ErrorReason.ProviderNotConfigured:
        return 'No AI provider configured. Open Arc1610 settings to set up a provider.';
      case ErrorReason.ProviderConnectionFailed:
        return 'Could not connect to the AI provider. Check your network and endpoint settings.';
      case ErrorReason.ProviderAuthFailed:
        return 'Authentication failed. Check your API key in Arc1610 settings.';
      case ErrorReason.ProviderRateLimit:
        return 'Rate limit exceeded. Please wait a moment and try again.';
      case ErrorReason.ProviderModelNotFound:
        return 'The specified model was not found. Check your model name in settings.';
      case ErrorReason.ProviderContextLength:
        return 'The request exceeded the model\'s context length. Try a shorter message or fewer context files.';
      case ErrorReason.ProviderTimeout:
        return 'Request timed out. The model may be loading or unavailable.';
      case ErrorReason.Cancelled:
        return 'Request was cancelled.';
      case ErrorReason.PathTraversal:
      case ErrorReason.OutsideWorkspace:
        return 'Access denied: the requested path is outside the workspace.';
      case ErrorReason.FileSecurityConcern:
        return 'This file is excluded for security reasons (e.g., secrets, keys, credentials).';
      default:
        return this.message;
    }
  }
}

/**
 * Type guard to check if an error is an abort/cancellation error.
 */
export function isCancellationError(error: unknown): boolean {
  if (error instanceof Arc1610Error && error.reason === ErrorReason.Cancelled) {
    return true;
  }
  if (error instanceof Error && error.name === 'AbortError') {
    return true;
  }
  if (error instanceof DOMException && error.name === 'AbortError') {
    return true;
  }
  return false;
}

/**
 * Wraps an unknown thrown value into an Error object.

/**
 * Wraps an unknown thrown value into an Error object.
 */
export function toError(thrown: unknown): Error {
  if (thrown instanceof Error) {
    return thrown;
  }
  if (typeof thrown === 'string') {
    return new Error(thrown);
  }
  return new Error(String(thrown));
}

import * as vscode from 'vscode';

/**
 * Structured logger that writes to a dedicated VS Code output channel.
 * All log entries include timestamps and severity levels.
 */
export class Logger {
  private static instance: Logger;
  private outputChannel: vscode.OutputChannel;

  private constructor() {
    this.outputChannel = vscode.window.createOutputChannel('Arc1610');
  }

  static getInstance(): Logger {
    if (!Logger.instance) {
      Logger.instance = new Logger();
    }
    return Logger.instance;
  }

  info(message: string, ...args: unknown[]): void {
    this.log('INFO', message, ...args);
  }

  warn(message: string, ...args: unknown[]): void {
    this.log('WARN', message, ...args);
  }

  error(message: string, ...args: unknown[]): void {
    this.log('ERROR', message, ...args);
  }

  debug(message: string, ...args: unknown[]): void {
    this.log('DEBUG', message, ...args);
  }

  private log(level: string, message: string, ...args: unknown[]): void {
    const timestamp = new Date().toISOString();
    const formatted = args.length > 0
      ? `[${timestamp}] [${level}] ${message} ${args.map(a => this.stringify(a)).join(' ')}`
      : `[${timestamp}] [${level}] ${message}`;
    this.outputChannel.appendLine(formatted);

    if (level === 'ERROR') {
      console.error(`[Arc1610] ${message}`, ...args);
    }
  }

  private stringify(value: unknown): string {
    if (value instanceof Error) {
      return `${value.message}\n${value.stack ?? ''}`;
    }
    if (typeof value === 'object') {
      try {
        return JSON.stringify(value, null, 2);
      } catch {
        return String(value);
      }
    }
    return String(value);
  }

  show(): void {
    this.outputChannel.show();
  }

  dispose(): void {

  }

  dispose(): void {
    this.outputChannel.dispose();
  }
}

import * as vscode from 'vscode';
import * as cp from 'child_process';
import { Logger } from './logger';

export class OllamaManager {
  private static isPrompting = false;

  /**
   * Check if Ollama is running. If not, prompt the user to start it.
   * Returns true if Ollama is running (or successfully started), false otherwise.
   */
  static async ensureRunning(endpoint: string = 'http://127.0.0.1:11434'): Promise<boolean> {
    const isRunning = await this.ping(endpoint);
    if (isRunning) {
      return true;
    }

    if (this.isPrompting) {
      return false; // Don't prompt multiple times simultaneously
    }

    this.isPrompting = true;
    try {
      const selection = await vscode.window.showWarningMessage(
        'Ollama is not currently running. Arc1610 needs it to generate code and index your workspace.',
        'Start Ollama',
        'Cancel'
      );

      if (selection === 'Start Ollama') {
        return await this.startOllama(endpoint);
      }
      return false;
    } finally {
      this.isPrompting = false;
    }
  }

  private static async ping(endpoint: string): Promise<boolean> {
    try {
      // The base endpoint typically returns "Ollama is running"
      const response = await fetch(endpoint, { signal: AbortSignal.timeout(2000) });
      return response.ok;
    } catch {
      return false;
    }
  }

  private static async startOllama(endpoint: string): Promise<boolean> {
    const logger = Logger.getInstance();

    return new Promise((resolve) => {
      logger.info('Attempting to start Ollama automatically...');

      try {
        // Run 'ollama serve' as a detached background process
        const child = cp.spawn('ollama', ['serve'], {
          detached: true,
          windowsHide: true,

        const child = cp.spawn('ollama', ['serve'], {
          detached: true,
          windowsHide: true,
          stdio: 'ignore'
        });

        // Unref so the VS Code extension host doesn't hang waiting for Ollama to close
        child.unref();
      } catch (error) {
        logger.error('Failed to spawn Ollama process', error);
        vscode.window.showErrorMessage('Failed to start Ollama. Make sure it is installed and in your system PATH.');
        resolve(false);
        return;
      }

      // Show progress while waiting for it to start up
      vscode.window.withProgress({
        location: vscode.ProgressLocation.Notification,
        title: "Starting Ollama...",
        cancellable: false
      }, async () => {
        // Poll for up to 10 seconds
        for (let i = 0; i < 10; i++) {
          await new Promise(r => setTimeout(r, 1000));
          const isUp = await this.ping(endpoint);
          if (isUp) {
            vscode.window.showInformationMessage('Ollama started successfully!');
            resolve(true);
            return;
          }
        }

        vscode.window.showErrorMessage('Ollama process started, but it is not responding to requests. You may need to start it manually.');
        resolve(false);
      });
    });
  }
}

