    }

    const current = stack.pop()!;

    let entries: string[];
    try {
      entries = await fs.readdir(current.absPath);
    } catch (error) {
      // Permission denied or inaccessible — skip silently
      logger.debug(`Cannot read directory: ${current.absPath}`);
      continue;
    }

